"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[82395],{74238:e=>{e.exports=JSON.parse('{"tag":{"label":"rats","permalink":"/docs/tags/rats","allTagsPath":"/docs/tags","count":30,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Rats/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Rats","description":"An overview of the most common health issues affecting pet rats, focusing on the chronic nature of Mycoplasma respiratory infections, the high incidence of mammary tumors, and conditions like bumblefoot.","permalink":"/docs/Rats/illnesses-and-conditions/common-health-issues"},{"id":"Rats/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in rats, focusing on the causes and prevention of incisor overgrowth (malocclusion) and the importance of providing a proper diet and chew toys.","permalink":"/docs/Rats/health-and-wellness/dental-health"},{"id":"Rats/illnesses-and-conditions/diabetes-in-rats","title":"diabetes-in-rats","description":"Rat Diabetes","permalink":"/docs/Rats/illnesses-and-conditions/diabetes-in-rats"},{"id":"Rats/getting-started/essential-rat-supplies","title":"Essential Rat Supplies","description":"Common Health Issues","permalink":"/docs/Rats/getting-started/essential-rat-supplies"},{"id":"Rats/health-and-wellness/eye-and-vision-issues","title":"eye-and-vision-issues","description":"A guide to common eye and vision issues in rats, explaining the significance of porphyrin (red tears) as a health indicator and discussing common infections and age-related blindness.","permalink":"/docs/Rats/health-and-wellness/eye-and-vision-issues"},{"id":"Rats/health-and-wellness/gi-health","title":"gi-health","description":"A guide to gastrointestinal (GI) health in rats, covering their omnivorous digestive system and the common causes of diarrhea, including diet, stress, and secondary effects from other illnesses.","permalink":"/docs/Rats/health-and-wellness/gi-health"},{"id":"Rats/getting-started/grooming-your-rat","title":"Grooming Your Rat","description":"Learn the best practices for rat grooming, including when and how to bathe them, how to trim their nails, and how to encourage their natural self-grooming habits.","permalink":"/docs/Rats/getting-started/grooming-your-rat"},{"id":"Rats/care-and-husbandry/hairless-rats","title":"hairless-rats","description":"A guide to caring for hairless rats, explaining their genetic background, unique care needs regarding temperature, diet, and skin health, and common health issues.","permalink":"/docs/Rats/care-and-husbandry/hairless-rats"},{"id":"Rats/health-and-wellness/home-health-care","title":"Home Health Care for Rats","description":"Learn how to perform a routine at-home health check for your pet rats to catch early signs of illness and ensure their long-term well-being.","permalink":"/docs/Rats/health-and-wellness/home-health-care"},{"id":"Rats/getting-started/is-a-rat-right-for-me","title":"is-a-rat-right-for-me","description":"Rats are among the most intelligent, affectionate, and interactive small pets you can keep. They learn their names, come when called, enjoy being held and carried, and form genuine bonds with their...","permalink":"/docs/Rats/getting-started/is-a-rat-right-for-me"},{"id":"Rats/illnesses-and-conditions/kidney-and-urinary-disorders","title":"kidney-and-urinary-disorders","description":"An in-depth guide to kidney and urinary disorders in rats, with a focus on Chronic Progressive Nephropathy (CPN), a common age-related disease.","permalink":"/docs/Rats/illnesses-and-conditions/kidney-and-urinary-disorders"},{"id":"Rats/illnesses-and-conditions/leptospirosis","title":"leptospirosis","description":"An important guide to leptospirosis in rats, a zoonotic bacterial disease, explaining its transmission, signs, and the critical importance of hygiene for pet owners.","permalink":"/docs/Rats/illnesses-and-conditions/leptospirosis"},{"id":"Rats/illnesses-and-conditions/mycoplasma-in-rats","title":"mycoplasma-in-rats","description":"If you\'re a rat owner, you\'ve likely heard the term \'myco.\' Mycoplasma pulmonis is a species of bacteria that is the primary cause of chronic respiratory disease (CRD) in pet rats. It\'s a pervasive...","permalink":"/docs/Rats/illnesses-and-conditions/mycoplasma-in-rats"},{"id":"Rats/health-and-wellness/parasites","title":"parasites","description":"A guide to common parasites affecting pet rats, including the intense itching caused by fur mites and lice, and the importance of veterinary-prescribed treatment.","permalink":"/docs/Rats/health-and-wellness/parasites"},{"id":"Rats/illnesses-and-conditions/parasites-in-rats","title":"parasites-in-rats","description":"Common Health Issues","permalink":"/docs/Rats/illnesses-and-conditions/parasites-in-rats"},{"id":"Rats/care-and-husbandry/playing-and-training","title":"playing-and-training","description":"A guide to playing with and training your pet rats, offering ideas for enrichment, toys, and teaching simple tricks to engage their intelligence.","permalink":"/docs/Rats/care-and-husbandry/playing-and-training"},{"id":"Rats/getting-started/proper-handling","title":"Proper Handling of Pet Rats","description":"Learn the best techniques for safely and confidently handling your pet rats, building a strong bond based on trust and positive reinforcement.","permalink":"/docs/Rats/getting-started/proper-handling"},{"id":"Rats/getting-started/rat-care-guide","title":"rat-care-guide","description":"Rat Behavior Guide","permalink":"/docs/Rats/getting-started/rat-care-guide"},{"id":"Rats/health-and-wellness/rat-dental-care","title":"rat-dental-care","description":"Common Health Issues","permalink":"/docs/Rats/health-and-wellness/rat-dental-care"},{"id":"Rats/health-and-wellness/rat-introductions","title":"rat-introductions","description":"Introducing a new rat to your existing group (or \'mischief\') is an exciting step, but it must be handled with care and patience. Rats are territorial and have complex social hierarchies. A proper...","permalink":"/docs/Rats/health-and-wellness/rat-introductions"},{"id":"Rats/getting-started/rat-nutrition-guide","title":"rat-nutrition-guide","description":"Proper nutrition is the cornerstone of your pet rat\'s health and longevity. As omnivores, rats have specific dietary needs that must be met to prevent obesity, nutritional deficiencies, and other...","permalink":"/docs/Rats/getting-started/rat-nutrition-guide"},{"id":"Rats/illnesses-and-conditions/rat-respiratory-infections-uris-guide","title":"rat-respiratory-infections-uris-guide","description":"Respiratory illness is one of the most common health issues affecting pet rats. Nearly all domestic rats are carriers of Mycoplasma pulmonis, the primary bacterium responsible for these infections...","permalink":"/docs/Rats/illnesses-and-conditions/rat-respiratory-infections-uris-guide"},{"id":"Rats/breeds-and-genetics/rat-sexing-guide","title":"rat-sexing-guide","description":"Correctly sexing rats is essential to prevent accidental litters and ensure proper housing. Rats can reproduce very young, and misidentification is one of the most common causes of surprise...","permalink":"/docs/Rats/breeds-and-genetics/rat-sexing-guide"},{"id":"Rats/getting-started/rat-treat-guide","title":"rat-treat-guide","description":"This guide is meant to help you quickly check whether a food is generally safe as a treat for your rats. Research on rat nutrition is limited, so some guidance is based on related species or...","permalink":"/docs/Rats/getting-started/rat-treat-guide"},{"id":"Rats/breeds-and-genetics/rat-variety-guide","title":"rat-variety-guide","description":"Welcome to the colorful world of fancy rats! Through selective breeding, pet rats have been developed in a stunning array of colors, coat types, and markings. While these varieties are fascinating,...","permalink":"/docs/Rats/breeds-and-genetics/rat-variety-guide"},{"id":"Rats/health-and-wellness/respiratory-issues","title":"respiratory-issues","description":"An in-depth guide to chronic respiratory disease in pet rats, caused by Mycoplasma pulmonis, covering the signs, triggers, and lifelong management of this ubiquitous condition.","permalink":"/docs/Rats/health-and-wellness/respiratory-issues"},{"id":"Rats/getting-started/the-ideal-rat-habitat-guide","title":"the-ideal-rat-habitat-guide","description":"A well-designed habitat is crucial for the health, happiness, and safety of your pet rats. As active, intelligent, and social creatures, they need a space that supports their natural behaviors like...","permalink":"/docs/Rats/getting-started/the-ideal-rat-habitat-guide"},{"id":"Rats/health-and-wellness/understanding-rat-behavior","title":"understanding-rat-behavior","description":"Rats are intelligent, social, and emotionally complex animals. Understanding their natural behaviors and unique ways of communicating is key to building a strong bond and providing them with the best...","permalink":"/docs/Rats/health-and-wellness/understanding-rat-behavior"},{"id":"Rats/illnesses-and-conditions/worms","title":"worms","description":"A guide to common internal worms in pet rats, such as pinworms and tapeworms, explaining that they are often asymptomatic and how they are diagnosed and treated.","permalink":"/docs/Rats/illnesses-and-conditions/worms"}],"unlisted":false}}')}}]);